//! SpecShakingMarker is an internal trait used to ensure that contract type specs
//! are included in the WASM binary when types are used at contract boundaries.
//!
//! The trait is called at three external boundary points:
//! 1. Contract function input parameters
//! 2. Contract function return values
//! 3. Event publishing
//!
//! Types that are only used internally (storage, cross-contract calls) do not
//! need their specs included, so the trait is NOT called from general TryFromVal
//! conversions.
//!
//! The trait has a default no-op implementation. Types generated by contracttype,
//! contractevent, and contracterror macros implement this trait to include their
//! spec XDR in the WASM's contractspecv0 section.
//!
//! Types whose layout includes their inner types inline (`Option<T>`,
//! `Result<T, E>`, tuples) call `T::spec_shaking_marker()` directly for
//! each inner type.
//!
//! Types whose size is independent of their inner types (`Vec<T>`,
//! `Map<K, V>`, `&T`, `&mut T`) use [`keep_reachable`] to reference each
//! inner type's marker without calling it. Recursive definitions are
//! possible through these types, so a direct call would risk a runtime cycle.

/// The magic prefix identifying a marker in the data section. Must match
/// `MAGIC` in `soroban_spec::shaking`.
const MARKER_MAGIC: [u8; 6] = *b"SpEcV1";

/// Builds the marker for a spec entry's XDR bytes: the magic prefix followed by
/// the first 8 bytes of the SHA-256 of the XDR.
///
/// This is a `const fn` so that macro-generated code derives the marker from the
/// same const-encoded bytes it embeds in the `contractspecv0` section. Hashing a
/// separately encoded copy of the spec would leave two encoders that must agree
/// forever, and a divergence would silently strip a spec entry that is in use.
#[doc(hidden)]
#[must_use]
pub const fn spec_marker(spec_entry_xdr: &[u8]) -> [u8; 14] {
    let h = sha256(spec_entry_xdr);
    [
        MARKER_MAGIC[0],
        MARKER_MAGIC[1],
        MARKER_MAGIC[2],
        MARKER_MAGIC[3],
        MARKER_MAGIC[4],
        MARKER_MAGIC[5],
        h[0],
        h[1],
        h[2],
        h[3],
        h[4],
        h[5],
        h[6],
        h[7],
    ]
}

/// SHA-256 round constants.
#[rustfmt::skip]
const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

/// SHA-256 of `input`, evaluatable at compile time.
///
/// A const implementation is needed because the marker is built while the
/// generated code compiles; `sha2` is not usable in a const context.
pub(crate) const fn sha256(input: &[u8]) -> [u8; 32] {
    let len = input.len();
    // Message is padded with a 0x80 byte, then zeroes, then the length in bits
    // as a big-endian u64, out to a multiple of the 64-byte block size.
    let padded = (len + 9).div_ceil(64) * 64;
    let bit_len = (len as u64) * 8;

    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];

    let mut base = 0;
    while base < padded {
        let mut w = [0u32; 64];

        // Load the block, reading padding bytes rather than materialising a
        // padded copy of the message.
        let mut t = 0;
        while t < 16 {
            let mut word = 0u32;
            let mut b = 0;
            while b < 4 {
                let p = base + t * 4 + b;
                let byte = if p < len {
                    input[p]
                } else if p == len {
                    0x80
                } else if p >= padded - 8 {
                    (bit_len >> (8 * (padded - 1 - p))) as u8
                } else {
                    0
                };
                word = (word << 8) | (byte as u32);
                b += 1;
            }
            w[t] = word;
            t += 1;
        }

        let mut t = 16;
        while t < 64 {
            let s0 = w[t - 15].rotate_right(7) ^ w[t - 15].rotate_right(18) ^ (w[t - 15] >> 3);
            let s1 = w[t - 2].rotate_right(17) ^ w[t - 2].rotate_right(19) ^ (w[t - 2] >> 10);
            w[t] = w[t - 16]
                .wrapping_add(s0)
                .wrapping_add(w[t - 7])
                .wrapping_add(s1);
            t += 1;
        }

        let (mut a, mut b, mut c, mut d) = (h[0], h[1], h[2], h[3]);
        let (mut e, mut f, mut g, mut hh) = (h[4], h[5], h[6], h[7]);

        let mut t = 0;
        while t < 64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA256_K[t])
                .wrapping_add(w[t]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
            t += 1;
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);

        base += 64;
    }

    let mut out = [0u8; 32];
    let mut i = 0;
    while i < 8 {
        let be = h[i].to_be_bytes();
        out[i * 4] = be[0];
        out[i * 4 + 1] = be[1];
        out[i * 4 + 2] = be[2];
        out[i * 4 + 3] = be[3];
        i += 1;
    }
    out
}

/// Trait for types that may include their spec in the WASM binary.
///
/// This trait is used internally by the SDK to ensure contract type specs
/// are included when types are used at external boundaries (function params,
/// return values, events).
///
/// Types with `#[contracttype]`, `#[contractevent]`, or `#[contracterror]`
/// will have implementations that include their spec. All other types have
/// a no-op implementation.
#[doc(hidden)]
pub trait SpecShakingMarker {
    /// Include this type's spec in the WASM binary.
    ///
    /// For primitive types and built-in SDK types, this is a no-op.
    /// For user-defined contract types, this ensures the spec XDR is
    /// included in the contractspecv0 section.
    #[inline(always)]
    fn spec_shaking_marker() {}
}

/// Keeps `f`'s symbol alive through the linker's dead-code-elimination
/// pass without invoking `f` at runtime. Takes `f` as a function pointer
/// and volatile-reads it. The same technique is used to keep the `MARKER`
/// byte statics alive (see `soroban-sdk-macros/src/shaking.rs`).
#[doc(hidden)]
#[inline(always)]
fn keep_reachable(_f: fn()) {
    #[cfg(target_family = "wasm")]
    let _ = unsafe { core::ptr::read_volatile(&_f) };
}

// Primitive type implementations (no-op)
impl SpecShakingMarker for () {}
impl SpecShakingMarker for bool {}
impl SpecShakingMarker for u32 {}
impl SpecShakingMarker for i32 {}
impl SpecShakingMarker for u64 {}
impl SpecShakingMarker for i64 {}
impl SpecShakingMarker for u128 {}
impl SpecShakingMarker for i128 {}

// Reference implementations — use `keep_reachable` because &T is
// pointer-sized independent of T, so recursive definitions through
// references could be possible. Currently, limitations of generics
// within `map_type` prevent this from working, so this is done
// out of caution.
impl<T: SpecShakingMarker> SpecShakingMarker for &T {
    #[inline(always)]
    fn spec_shaking_marker() {
        keep_reachable(T::spec_shaking_marker);
    }
}

impl<T: SpecShakingMarker> SpecShakingMarker for &mut T {
    #[inline(always)]
    fn spec_shaking_marker() {
        keep_reachable(T::spec_shaking_marker);
    }
}

// Option implementation - includes inner type's spec
impl<T: SpecShakingMarker> SpecShakingMarker for Option<T> {
    #[inline(always)]
    fn spec_shaking_marker() {
        T::spec_shaking_marker();
    }
}

// Result implementation - includes both types' specs
impl<T: SpecShakingMarker, E: SpecShakingMarker> SpecShakingMarker for Result<T, E> {
    #[inline(always)]
    fn spec_shaking_marker() {
        T::spec_shaking_marker();
        E::spec_shaking_marker();
    }
}

